// Applied rules: [III④, III③]
// Skipped rules: [C4: Hit [3] is not a byte-serial pointer traversal over contiguous bytes; it is an open-addressing hash-table probe loop whose progress condition depends on entry metadata, with only library/string checks inside. There is no sound 8-byte cursor-widening opportunity matching C4's required shape.]
unsafe fn xmlDictFindEntry(
    mut dict: *const xmlDict,
    mut prefix: *const xmlChar,
    mut name: *const xmlChar,
    mut len: c_int,
    mut hashValue: c_uint,
    mut pfound: *mut c_int,
) -> *mut xmlDictEntry {
    let mut mask: c_uint = 0;
    let mut pos: c_uint = 0;
    let mut displ: c_uint = 0;
    let mut found: c_int = 0 as c_int;

    mask = (*dict).size.wrapping_sub(1 as size_t) as c_uint;
    pos = hashValue & mask;

    let table_len = (*dict).size as usize;
    // SAFETY: `(*dict).table` is the dictionary's hash table base and `(*dict).size`
    // is its stable entry count for this region; callers provide a valid non-null
    // dictionary/table, and we create only a shared slice, so no mutable aliasing is introduced.
    let table = unsafe { core::slice::from_raw_parts((*dict).table as *const xmlDictEntry, table_len) };

    if table.get_unchecked(pos as usize).hashValue != 0 as c_uint {
        displ = 0 as c_uint;
        loop {
            let current = table.get_unchecked(pos as usize);
            if current.hashValue == hashValue {
                if prefix.is_null() {
                    // SAFETY: `name` is compared for exactly `len` bytes as in the original
                    // `strncmp` call, so the caller must provide at least that many readable bytes.
                    let name_bytes = unsafe { core::slice::from_raw_parts(name, len as usize) };
                    // SAFETY: `current.name` is read for exactly `len` bytes, and the original code
                    // also reads the trailing byte at `len`; caller/table invariants guarantee the
                    // stored string is readable for that span. This is a shared view only.
                    let entry_name_bytes =
                        unsafe { core::slice::from_raw_parts(current.name, len as usize) };
                    if entry_name_bytes == name_bytes
                        && *current.name.offset(len as isize) as c_int == 0 as c_int
                    {
                        found = 1 as c_int;
                        break;
                    }
                } else if xmlStrQEqual(prefix, name, current.name) != 0 {
                    found = 1 as c_int;
                    break;
                }
            }
            displ = displ.wrapping_add(1);
            pos = pos.wrapping_add(1);
            if pos & mask == 0 as c_uint {
                pos = 0 as c_uint;
            }
            let next = table.get_unchecked(pos as usize);
            if !(next.hashValue != 0 as c_uint
                && pos.wrapping_sub(next.hashValue) & mask >= displ)
            {
                break;
            }
        }
    }
    let entry = table.as_ptr().add(pos as usize) as *mut xmlDictEntry;
    *pfound = found;
    return entry;
}

